import{c as t,Q as o,j as r,m as d}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Session Blindspot Review — 用 T1–T11 回審 v5 重寫","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/2026-07-26-session-unknowns-review.md","filePath":"research/reports/2026-07-26-session-unknowns-review.md","lastUpdated":1785909234000}'),s={name:"research/reports/2026-07-26-session-unknowns-review.md"};function a(n,e,c,i,h,l){return o(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="session-blindspot-review-—-用-t1–t11-回審-v5-重寫" tabindex="-1">Session Blindspot Review — 用 T1–T11 回審 v5 重寫 <a class="header-anchor" href="#session-blindspot-review-—-用-t1–t11-回審-v5-重寫" aria-label="Permalink to &quot;Session Blindspot Review — 用 T1–T11 回審 v5 重寫&quot;">​</a></h1><blockquote><p>對象：2026-07-26 的 The Loop Harness v5 重寫 session（約 40 個 commit）。 框架：thariqs <code>html-effectiveness/unknowns</code>（T1–T11）+ Anthropic《The new rules of context engineering for Claude 5 generation models》。 立場：<strong>證偽式</strong>——找我做錯了什麼，不找我做對了什麼。</p></blockquote><h2 id="_0-一個必須先問的問題-v5-是否走反了方向" tabindex="-1">0. 一個必須先問的問題：v5 是否走反了方向？ <a class="header-anchor" href="#_0-一個必須先問的問題-v5-是否走反了方向" aria-label="Permalink to &quot;0. 一個必須先問的問題：v5 是否走反了方向？&quot;">​</a></h2><p>Blog 第 1 條：移除過度約束的指令，Anthropic 砍掉 Claude Code system prompt 的 80% 而無性能損失。 v5 卻<strong>新增</strong>了 <code>loop.md</code> + <code>graph.md</code> 兩個常駐檔。表面上正好相反。</p><p>量測後才發現我先前盯錯指標：</p><table tabindex="0"><thead><tr><th></th><th>auto-load</th><th>全文層</th><th><strong>教義總表面</strong></th></tr></thead><tbody><tr><td>v4</td><td>18,931</td><td><code>HARNESS-CORE-v4.md</code> 25,732</td><td><strong>44,663</strong></td></tr><tr><td>v5</td><td>22,785</td><td>無（單一 canonical 裁決）</td><td><strong>22,785</strong></td></tr></tbody></table><p>v5 的 auto-load 漲了約 3,900，但<strong>教義總量砍半</strong>——消滅了 25,732 bytes 的重複全文層。方向與 blog 一致。</p><p><strong>但我先前整輪都在盯 auto-load 那個數字</strong>，甚至為它做了門檻上調的程序瑕疵辯護（見 <code>model-profiles.md</code> §2.1 的 PROVISIONAL 聲明）。這本身就是 <code>core.md §TEST</code>「Gate 選擇稽核：非 proxy 子集」的實例——我用一個子集指標代表了整體。</p><p><strong>後續已結案</strong>：<code>graph.md</code> 的閘門語密度只有 <strong>13%</strong>（<code>core.md</code> 35%、<code>loop.md</code> 47%），意即它大半是判斷指引而非閘門。依 blog 第 1 條與 <code>core.md</code>「程序性指導與能力成反比」，<strong>graph.md 是 v5 中最該再剪的一檔</strong>。已於 <code>7af6e2b</code> 剪枝——同一輪順帶吸收了外部 Graph Engineering 視角的兩條新條文，仍達成淨剪：剪掉的是已由 <code>refs/delegation-protocol.md</code> 擁有的效益清單、三處重複表述的 verify 檔位選擇、以及屬歷史敘述的吸收說明，<code>[E]</code>/<code>[E*]</code> 一字未動。</p><hr><h2 id="_1-逐技巧回審" tabindex="-1">1. 逐技巧回審 <a class="header-anchor" href="#_1-逐技巧回審" aria-label="Permalink to &quot;1. 逐技巧回審&quot;">​</a></h2><h3 id="t1-blindspot-pass-—-本-session-最大的缺席" tabindex="-1">T1 Blindspot Pass — 本 session 最大的缺席 <a class="header-anchor" href="#t1-blindspot-pass-—-本-session-最大的缺席" aria-label="Permalink to &quot;T1 Blindspot Pass — 本 session 最大的缺席&quot;">​</a></h3><p><strong>沒做的事</strong>：改 4 支 hook 的輸出通道前，沒有掃過「這些 hook 到底在哪個執行路徑上開火」。</p><p><strong>代價</strong>：F19 對應的 <code>taste-reference-lint.sh</code> 只接在 <code>PreToolUse(Agent|Workflow)</code>，而 F19 的 fixture 是<strong>直接使用者請求</strong>——hook 根本不在該路徑上。我卻把那個 commit 標題寫成「處理 F19 紅軸」。<strong>換通道不可能移動一條 Body 不在路徑上的軸。</strong></p><p>更難堪的是：v4 backlog 早就寫著「TASTE_RE 補模糊詞（待執行）」，而 F19 fixture 的原句「專業一點」正是 TASTE_RE 沒有的詞。<strong>線索在檔案裡躺著，我沒去 Blindspot Pass 就先動手。</strong></p><p>已修（覆蓋擴大、非放寬）：接上 <code>UserPromptSubmit</code>、payload 兩種形狀都吃、補模糊品味詞、<code>hookEventName</code> 改動態。</p><h3 id="t7-point-at-a-reference-—-我餵了一個會漂移的「reference」" tabindex="-1">T7 Point at a Reference — 我餵了一個會漂移的「reference」 <a class="header-anchor" href="#t7-point-at-a-reference-—-我餵了一個會漂移的「reference」" aria-label="Permalink to &quot;T7 Point at a Reference — 我餵了一個會漂移的「reference」&quot;">​</a></h3><p><strong>做錯的事</strong>：給 Fable 5 做 <code>[E]</code> 對等性審查時，v4 對照組用 <code>git show HEAD~1</code> 抽取。</p><p><strong>為什麼錯</strong>：auto-sync commit 在期間落地，<code>HEAD~1</code> 已經漂移到 v5 重寫 commit 本身。結果索引的「v4 節」與「v5 節」內容相同，<code>subagent-strategy.md</code> 那節全空（該 rev 檔已刪）。</p><p><strong>若 verifier 採信該索引</strong>，會得出「<code>[E]</code> 一字未動、<code>subagent-strategy</code> 無 <code>[E]</code> 可失」的<strong>完美假陰性</strong>，再疊上我 commit message 的自報收據，形成三層自證閉環。</p><p><strong>沒出事的原因不是我</strong>：Fable 未採信該索引，自行回具名 rev 取真本。這是 <code>graph.md §G5</code>「verdict 非證據，採信前機械重驗」在對方身上生效，不是在我身上。</p><p><strong>正解</strong>：reference 必須是<strong>不會漂移的具名 SHA</strong>，不是相對 ref。這正是 T7「Point at a Reference」的字面意思——我提供了一個指標，但那個指標會動。</p><h3 id="t9-implementation-notes-—-三次「先做後發現」" tabindex="-1">T9 Implementation Notes — 三次「先做後發現」 <a class="header-anchor" href="#t9-implementation-notes-—-三次「先做後發現」" aria-label="Permalink to &quot;T9 Implementation Notes — 三次「先做後發現」&quot;">​</a></h3><p>三個本可用 T9 攔下的偏離，我都是做完才發現：</p><table tabindex="0"><thead><tr><th>偏離</th><th>發現時點</th><th>若有 T9</th></tr></thead><tbody><tr><td>fixtures 遷入 v5 並改名 <code>EVAL-PACK-v5-*</code></td><td>使用者指出後才反轉</td><td>寫下「為何改名」時就會問「它量測的是哪版契約」</td></tr><tr><td><code>EVAL-BASELINE-v5</code> 命名</td><td>使用者詢問時才查出內文寫著 v4</td><td>同上</td></tr><tr><td><code>PORTABLE-PROMPT-KIT</code> 遷入</td><td>使用者指出後才刪</td><td>同上</td></tr></tbody></table><p><strong>三次同一個簽名</strong>：舊世代內容穿 v5 檔名。<code>core.md §RECORD</code> 說「同簽名重現 ≥2 次才改規則」——這裡是 3 次（連同 <code>HARNESS-CARD</code>、<code>.factory</code>、<code>evals/INDEX</code> 共 <strong>6 次</strong>），早已越過門檻。</p><h3 id="t3-four-design-directions-—-靜默錨定了第一個可行解" tabindex="-1">T3 Four Design Directions — 靜默錨定了第一個可行解 <a class="header-anchor" href="#t3-four-design-directions-—-靜默錨定了第一個可行解" aria-label="Permalink to &quot;T3 Four Design Directions — 靜默錨定了第一個可行解&quot;">​</a></h3><p>fixtures 該遷入 v5 還是留在封存，我<strong>沒有列成選項</strong>，直接選了「遷入」並給了一個聽起來合理的理由（「fixtures 是量測工具不隨契約過期」）。</p><p>該理由站不住：這些 fixture 的 <code>deterministic_check</code> 是<strong>對 v3/v4 條文撰寫並凍結</strong>的。若當初列出兩個方向，「它們綁定哪一版條文」這個問題會在選之前浮出來。</p><p><code>core.md §PROPOSE</code> 本來就寫著「scope 有量級選擇時列 ≥2 級由使用者選，不靜默錨定第一個可行解」——<strong>我違反了自己剛寫進去的條文</strong>。</p><h3 id="t6-the-interview-—-做對的一次" tabindex="-1">T6 The Interview — 做對的一次 <a class="header-anchor" href="#t6-the-interview-—-做對的一次" aria-label="Permalink to &quot;T6 The Interview — 做對的一次&quot;">​</a></h3><p>「四個相關的 playbook」是我自己上一則訊息裡講得不精確的詞。我沒有猜，用 <code>AskUserQuestion</code> 列出四個選項讓使用者選，並標明推薦與理由。刪錯 playbook 是不可逆的，這裡問對了。</p><h3 id="t11-quiz-me-before-i-merge-—-結構上做到-形式上沒有" tabindex="-1">T11 Quiz Me Before I Merge — 結構上做到，形式上沒有 <a class="header-anchor" href="#t11-quiz-me-before-i-merge-—-結構上做到-形式上沒有" aria-label="Permalink to &quot;T11 Quiz Me Before I Merge — 結構上做到，形式上沒有&quot;">​</a></h3><p>每個 commit 前跑 <code>healthcheck</code> / <code>check-references</code> / <code>check-anchors</code> 並展示輸出，實質是機械版的 T11。但<strong>沒有一次是針對「我是否真的理解這個改動的下游影響」</strong>——<code>generator-ref-check</code> 要防的四次失效，正是「改動的下游影響沒被檢查」。</p><p>已機械化：新增 <code>generator-ref-check.sh</code>（PreToolUse Bash），刪除／搬移路徑前自動列出硬編碼引用它的腳本。</p><h3 id="t2-t4-t5-t8-t10-—-本-session-不適用" tabindex="-1">T2 / T4 / T5 / T8 / T10 — 本 session 不適用 <a class="header-anchor" href="#t2-t4-t5-t8-t10-—-本-session-不適用" aria-label="Permalink to &quot;T2 / T4 / T5 / T8 / T10 — 本 session 不適用&quot;">​</a></h3><p>分別是需求詞彙轉譯、可點擊原型、干預時間軸、可調計畫、買單文件。本 session 是既有系統的重構，需求由使用者逐輪明確給出，這五項無施力點。<strong>列出來是為了說明「沒用」是判斷結果而非遺漏。</strong></p><hr><h2 id="_2-跨技巧的單一根因" tabindex="-1">2. 跨技巧的單一根因 <a class="header-anchor" href="#_2-跨技巧的單一根因" aria-label="Permalink to &quot;2. 跨技巧的單一根因&quot;">​</a></h2><p>上述 T1 / T7 / T9 的失效，加上本 session 其餘幾次，可歸為<strong>同一類</strong>：</p><blockquote><p><strong>我採信了一個報告狀態的東西，卻沒有先驗那個東西本身。</strong></p></blockquote><table tabindex="0"><thead><tr><th>#</th><th>被採信的 oracle</th><th>它錯在哪</th><th>後果</th></tr></thead><tbody><tr><td>1</td><td><code>git show HEAD~1</code></td><td>auto-sync 使其漂移</td><td>餵給 verifier 的對照組是 v5 自己</td></tr><tr><td>2</td><td>我自寫的章節級掃描器</td><td>regex 只抓第一個詞，<code>§The Loop</code> 被截成 <code>§The</code></td><td>回報 135 筆懸空，絕大多數是誤判</td></tr><tr><td>3</td><td><code>f11</code> fixture 的 <code>deterministic_check</code></td><td>known-good 與 known-bad 皆 PASS</td><td>零區辨力，分數不可採信</td></tr><tr><td>4</td><td>我自算的 <code>EXPECTED_SETTINGS</code></td><td>我數 hook 命令數，healthcheck 數 matcher 群組數</td><td>寫入 32 導致 FAIL</td></tr><tr><td>5</td><td><code>check-references</code> 的 <code>dangling=0</code></td><td>只驗檔案級，章節級未涵蓋</td><td>拿 proxy 子集當完整覆蓋</td></tr><tr><td>6</td><td>auto-load byte 數</td><td>只是教義總表面的一半</td><td>為子集指標做了門檻上調辯護</td></tr></tbody></table><p>六次中只有 #3、#5 發生在 loop 內。而 <code>loop.md §L4</code> 的 oracle 資格條文，<strong>範圍寫的是「建 loop 前」</strong>——另外四次因此不在其涵蓋內。</p><p><strong>這是條文的 scope bug，不是執行者的疏忽。</strong></p><h3 id="已修" tabindex="-1">已修 <a class="header-anchor" href="#已修" aria-label="Permalink to &quot;已修&quot;">​</a></h3><p><code>core.md §TEST</code> 的條文由</p><blockquote><p>Oracle 資格<strong>先於 loop</strong>：壞 oracle 比沒有更糟</p></blockquote><p>改為</p><blockquote><p>Oracle 資格<strong>先於採信</strong>：<strong>任何用來判定真偽的東西都是 oracle</strong>——test、checker script、索引、baseline、<code>git</code> ref、你自己剛寫的 grep。採信其輸出前先驗它能區辨已知好／已知壞。</p></blockquote><p>+199 bytes，常駐 22,785（門檻 23,000 內）。這是<strong>閘門加嚴</strong>，符合「驗證閘門與能力成正比」。</p><hr><h2 id="_3-本輪落地的兩個機械化" tabindex="-1">3. 本輪落地的兩個機械化 <a class="header-anchor" href="#_3-本輪落地的兩個機械化" aria-label="Permalink to &quot;3. 本輪落地的兩個機械化&quot;">​</a></h2><table tabindex="0"><thead><tr><th>修</th><th>防的失效</th><th>型態</th><th>收據</th></tr></thead><tbody><tr><td><code>core.md §TEST</code> oracle 範圍擴大</td><td>上表六次中的四次（loop 外的 oracle）</td><td>條文加嚴</td><td>byte 量測在門檻內</td></tr><tr><td><code>generator-ref-check.sh</code>（PreToolUse Bash）</td><td>生成器復活死節點（session 內 4 次）</td><td>可見提醒、不阻斷</td><td>正例列出 4 支硬編碼腳本；三個反例（repo 外路徑／非刪除指令／無引用檔）全靜默</td></tr></tbody></table><p><code>generator-ref-check</code> 刻意不阻斷：硬編碼引用不等於不能刪，多數情況是「刪之前先改腳本」。阻斷會擋住正當操作；正確強度是<strong>在該知道的時點把清單攤開</strong>。</p><hr><h2 id="_4-明確不修的" tabindex="-1">4. 明確不修的 <a class="header-anchor" href="#_4-明確不修的" aria-label="Permalink to &quot;4. 明確不修的&quot;">​</a></h2><table tabindex="0"><thead><tr><th>項</th><th>為何不修</th></tr></thead><tbody><tr><td><code>pre-commit-review</code> 三個誤傷</td><td>屬閘門變更，<code>core.md §APPLY</code> 要求先過異 context 對抗複審</td></tr><tr><td><code>.factory</code> port 過期</td><td>已止血（過期警語），修復需使用者裁決 generated-vs-雙軌</td></tr><tr><td>v5 fixtures 與 baseline</td><td>需獨立撰寫（backlog #9/#5），非本 review 範圍</td></tr></tbody></table><hr><h2 id="_5-給下一個-session-的一句話" tabindex="-1">5. 給下一個 session 的一句話 <a class="header-anchor" href="#_5-給下一個-session-的一句話" aria-label="Permalink to &quot;5. 給下一個 session 的一句話&quot;">​</a></h2><p>這個 session 的所有主要失誤，都不是「不知道規則」——<strong>六條規則我全都寫在 <code>core.md</code> 裡，然後逐條違反</strong>（Gate 選擇稽核、oracle 資格、列 ≥2 級選項、數字對帳、verdict 非證據、避免與 agent 動同一批檔）。</p><p>規則已經夠了。<strong>缺的是在該檢查的時點會自己開火的東西</strong>——所以本輪的產出是兩個機械化，不是六條新規則。</p>',61)])])}const b=t(s,[["render",a]]);export{g as __pageData,b as default};
